import{_ as a,m as n,k as t,ah as i}from"./chunks/framework.HEc25T99.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"fr/users/support/faq.md","filePath":"src/fr/users/support/faq.md"}'),s={name:"fr/users/support/faq.md"};function r(o,e,u,l,c,d){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Questions fréquentes sur l&#39;utilisation de l&#39;administration Creopse. Si votre question n&#39;est pas ici, contactez votre administrateur.</p><h2 id="contenu-publication" tabindex="-1">Contenu &amp; publication <a class="header-anchor" href="#contenu-publication" aria-label="Permalink to &quot;Contenu &amp; publication&quot;">​</a></h2><h3 id="j-ai-modifie-une-section-mais-rien-n-a-change-sur-le-site-public" tabindex="-1">J&#39;ai modifié une section mais rien n&#39;a changé sur le site public <a class="header-anchor" href="#j-ai-modifie-une-section-mais-rien-n-a-change-sur-le-site-public" aria-label="Permalink to &quot;J&#39;ai modifié une section mais rien n&#39;a changé sur le site public&quot;">​</a></h3><p>Il manque probablement l&#39;étape de publication : dans l&#39;<a href="./../sections/visual-editor.html">éditeur visuel</a>, les modifications ne deviennent visibles publiquement qu&#39;après avoir cliqué sur <strong>Publier</strong>. Le bouton <strong>Aperçu</strong> permet de vérifier le rendu avant de publier.</p><h3 id="comment-ajouter-une-nouvelle-page-ou-reorganiser-ses-sections" tabindex="-1">Comment ajouter une nouvelle page ou réorganiser ses sections ? <a class="header-anchor" href="#comment-ajouter-une-nouvelle-page-ou-reorganiser-ses-sections" aria-label="Permalink to &quot;Comment ajouter une nouvelle page ou réorganiser ses sections ?&quot;">​</a></h3><p>Depuis <a href="./../sections/content-management.html">Gestion de contenu</a>, la liste de pages propose <strong>Ajouter une page</strong> et <strong>Réorganiser les pages</strong>. Une fois une page sélectionnée, ses sections peuvent être réordonnées, affichées/masquées, ou modifiées directement.</p><h3 id="je-ne-trouve-pas-comment-attacher-une-nouvelle-section-a-une-page" tabindex="-1">Je ne trouve pas comment attacher une nouvelle section à une page <a class="header-anchor" href="#je-ne-trouve-pas-comment-attacher-une-nouvelle-section-a-une-page" aria-label="Permalink to &quot;Je ne trouve pas comment attacher une nouvelle section à une page&quot;">​</a></h3><p>Depuis la page concernée (dans <a href="./../sections/content-management.html">Gestion de contenu</a>), le bloc <strong>Insérer ou retirer des sections</strong> permet d&#39;en ajouter une. La même action est aussi disponible depuis l&#39;<a href="./../sections/visual-editor.html">éditeur visuel</a>.</p><h3 id="quelle-difference-entre-les-statuts-d-un-article-brouillon-en-attente-publie" tabindex="-1">Quelle différence entre les statuts d&#39;un article (Brouillon, En attente, Publié) ? <a class="header-anchor" href="#quelle-difference-entre-les-statuts-d-un-article-brouillon-en-attente-publie" aria-label="Permalink to &quot;Quelle différence entre les statuts d&#39;un article (Brouillon, En attente, Publié) ?&quot;">​</a></h3><p><strong>Brouillon</strong> n&#39;est visible que par son auteur, <strong>En attente</strong> signale un article prêt mais en attente de validation, et <strong>Publié</strong> est visible sur le site public. Voir <a href="./../sections/news-management.html">Gestion des news</a>.</p><h3 id="le-contenu-d-une-section-ne-s-affiche-pas-dans-une-langue" tabindex="-1">Le contenu d&#39;une section ne s&#39;affiche pas dans une langue <a class="header-anchor" href="#le-contenu-d-une-section-ne-s-affiche-pas-dans-une-langue" aria-label="Permalink to &quot;Le contenu d&#39;une section ne s&#39;affiche pas dans une langue&quot;">​</a></h3><p>Vérifiez que le champ correspondant a bien été renseigné pour cette langue — le contenu de Creopse est bilingue par champ, une valeur manquante dans une langue reste vide plutôt que de reprendre l&#39;autre langue automatiquement.</p><h2 id="medias" tabindex="-1">Médias <a class="header-anchor" href="#medias" aria-label="Permalink to &quot;Médias&quot;">​</a></h2><h3 id="j-ai-supprime-un-fichier-par-erreur-peut-on-le-recuperer" tabindex="-1">J&#39;ai supprimé un fichier par erreur, peut-on le récupérer ? <a class="header-anchor" href="#j-ai-supprime-un-fichier-par-erreur-peut-on-le-recuperer" aria-label="Permalink to &quot;J&#39;ai supprimé un fichier par erreur, peut-on le récupérer ?&quot;">​</a></h3><p>Oui, tant qu&#39;il n&#39;a pas été supprimé définitivement : l&#39;onglet <strong>Corbeille</strong> de la <a href="./../sections/media-library.html">Médiathèque</a> regroupe les fichiers supprimés et permet de les restaurer.</p><h2 id="utilisateurs-acces" tabindex="-1">Utilisateurs &amp; accès <a class="header-anchor" href="#utilisateurs-acces" aria-label="Permalink to &quot;Utilisateurs &amp; accès&quot;">​</a></h2><h3 id="comment-ajouter-un-nouvel-administrateur" tabindex="-1">Comment ajouter un nouvel administrateur ? <a class="header-anchor" href="#comment-ajouter-un-nouvel-administrateur" aria-label="Permalink to &quot;Comment ajouter un nouvel administrateur ?&quot;">​</a></h3><p>Depuis <a href="./../sections/user-management.html">Gestion des utilisateurs</a>, le bouton <strong>Ajouter</strong> crée un nouveau compte, auquel un rôle est ensuite attribué depuis <a href="./../sections/access-management.html">Gestion d&#39;accès</a>.</p><h3 id="je-n-ai-pas-acces-a-une-rubrique-que-je-devrais-pourtant-voir" tabindex="-1">Je n&#39;ai pas accès à une rubrique que je devrais pourtant voir <a class="header-anchor" href="#je-n-ai-pas-acces-a-une-rubrique-que-je-devrais-pourtant-voir" aria-label="Permalink to &quot;Je n&#39;ai pas accès à une rubrique que je devrais pourtant voir&quot;">​</a></h3><p>Cela dépend des permissions associées à votre rôle. Demandez à un administrateur de vérifier votre rôle dans <a href="./../sections/access-management.html">Gestion d&#39;accès</a>, ou consultez votre rôle actuel depuis <a href="./../sections/account-info.html">Informations du compte</a>.</p><h2 id="compte" tabindex="-1">Compte <a class="header-anchor" href="#compte" aria-label="Permalink to &quot;Compte&quot;">​</a></h2><h3 id="j-ai-oublie-mon-mot-de-passe" tabindex="-1">J&#39;ai oublié mon mot de passe <a class="header-anchor" href="#j-ai-oublie-mon-mot-de-passe" aria-label="Permalink to &quot;J&#39;ai oublié mon mot de passe&quot;">​</a></h3><p>Utilisez le lien de récupération sur la page de connexion. Une fois connecté, le mot de passe peut être changé à tout moment depuis <a href="./../sections/account-info.html">Informations du compte</a> (cliquer sur l&#39;icône crayon à côté du champ <strong>Mot de passe</strong>).</p><h3 id="je-n-ai-pas-recu-l-email-de-verification-de-mon-compte" tabindex="-1">Je n&#39;ai pas reçu l&#39;email de vérification de mon compte <a class="header-anchor" href="#je-n-ai-pas-recu-l-email-de-verification-de-mon-compte" aria-label="Permalink to &quot;Je n&#39;ai pas reçu l&#39;email de vérification de mon compte&quot;">​</a></h3><p>Vérifiez vos courriers indésirables (spams) — le bandeau affiché sur la <a href="./../sections/dashboard.html">Vue d&#39;ensemble</a> permet aussi de renvoyer le lien de vérification.</p><h2 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions&quot;">​</a></h2><h3 id="une-extension-est-elle-sans-risque-a-installer" tabindex="-1">Une extension est-elle sans risque à installer ? <a class="header-anchor" href="#une-extension-est-elle-sans-risque-a-installer" aria-label="Permalink to &quot;Une extension est-elle sans risque à installer ?&quot;">​</a></h3><p>Une extension a accès à votre site une fois installée — n&#39;installez que des extensions provenant d&#39;une source de confiance. Voir <a href="./../sections/plugins.html">Extensions</a>.</p>',29)])])}const h=a(s,[["render",r]]);export{m as __pageData,h as default};
